function heading(title,desc,button){const host=$('#other-view');host.replaceChildren();const head=document.createElement('div');head.className='view-heading';const div=document.createElement('div'),h=document.createElement('h1'),p=document.createElement('p');h.textContent=title;p.textContent=desc;div.append(h,p);head.append(div);if(button)head.append(button);host.append(head);return host;}
function button(text,fn,cls='primary'){const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b;}
function showLibrary(){setView('library');const host=heading(courseName(db.course)+'词库',`${courseWords().length} 个词条 · ${eligible().length} 词可用于当前模式`);const search=document.createElement('input');search.className='search';search.placeholder='搜索英文或中文释义';search.setAttribute('aria-label','搜索词库');const list=document.createElement('div'),pager=document.createElement('div');pager.className='pager';host.append(search,list,pager);let page=0;function render(){const term=search.value.trim().toLowerCase();const found=courseWords().filter(w=>w.word.includes(term)||w.zh.includes(term));list.replaceChildren();found.slice(page*30,(page+1)*30).forEach(w=>list.append(wordRow(w,false)));if(!found.length)list.textContent='没有找到这个词，试试其他关键词。';pager.replaceChildren();const prev=button('上一页',()=>{page--;render()},'lesson-button'),next=button('下一页',()=>{page++;render()},'lesson-button');prev.disabled=page===0;next.disabled=(page+1)*30>=found.length;pager.append(prev,document.createTextNode(`${page+1} / ${Math.max(1,Math.ceil(found.length/30))}`),next);}search.oninput=()=>{page=0;render()};render();}
function wordRow(w,review){const row=document.createElement('div');row.className='list-row';const strong=document.createElement('strong'),p=document.createElement('p');strong.textContent=w.word;p.textContent=w.zh;row.append(strong,p);row.append(button(review?'移出复习':'练这个词',()=>{if(review){delete db.mistakes[w.word];persist();updateSidebar();showReview();}else{if(mode==='cloze')mode='follow';if((mode==='dictation'&&!w.en)||(mode==='cloze'&&!w.sentence)){toast('此词缺少当前模式的材料，已切换跟练');mode='follow';}startSession();queue=[w];index=0;renderWord();}},''));return row;}
function showReview(){setView('review');const list=courseWords().filter(w=>db.mistakes[w.word]);const action=button('开始复习',()=>startSession(true));action.disabled=!list.length;const host=heading('错词复习',`${list.length} 词`,action);if(!list.length){const e=document.createElement('div');e.className='empty';e.innerHTML='<h2>A fresh start.</h2><p>暂无错词</p>';host.append(e);return;}list.forEach(w=>host.append(wordRow(w,true)));}
