$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error();const d=JSON.parse(await f.text());if(d.version!==1||!d.mastered||!d.mistakes||!d.days)throw Error();const known=new Set(allWords.map(w=>w.word));for(const [w,n]of Object.entries(d.mastered)){if(known.has(w)&&Number.isFinite(n)&&n>0)db.mastered[w]=Math.max(db.mastered[w]||0,n);}for(const [w,m]of Object.entries(d.mistakes)){if(known.has(w))db.mistakes[w]={at:Number(m.at)||Date.now(),count:Number(m.count)||0};}for(const [date,entry]of Object.entries(d.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!entry.words)continue;const clean=Object.fromEntries(Object.keys(entry.words).filter(w=>known.has(w)).map(w=>[w,true]));const old=db.days[date]||{words:{},seconds:0};db.days[date]={words:{...old.words,...clean},seconds:Math.max(old.seconds,Math.max(0,Number(entry.seconds)||0))};}if(d.memory&&typeof d.memory==='object'){db.memory||={};for(const [w,m]of Object.entries(d.memory)){if(known.has(w)&&m&&Number.isFinite(m.due)&&Number.isInteger(m.streak)&&m.streak>=0&&m.streak<=5)db.memory[w]={due:m.due,streak:m.streak,lapses:Math.max(0,Number(m.lapses)||0)};}}mergeRecordLogs(d.logs);mergePassageData(d);persist();updateSidebar();toast('备份已合并，现有进度已保留');}catch{toast('备份格式不正确，请选择畅记导出的 JSON 文件');}e.target.value='';};
document.addEventListener('keydown',e=>{if($('#settings-dialog').open)return;if(e.key==='Enter'&&view==='stats'&&$('#continue')){e.preventDefault();$('#continue').click();return;}if(view!=='practice')return;if(mode==='cloze'){if(e.key==='Tab'&&!e.shiftKey&&!e.ctrlKey&&!e.altKey&&!e.metaKey&&(e.target===$('#passage-input')||e.target===$('#passage-next')||e.target===document.body||e.target.closest?.('#passage-details'))){e.preventDefault();if(!e.repeat)togglePassageDetails();}return;}const isTyping=e.target===$('#typing');if(solved&&isTyping&&/^[a-zA-Z]$/.test(e.key)){if(db.settings.auto){nextWord();if(view!=='practice'){e.preventDefault();return;}}else{e.preventDefault();return;}}if(e.code==='Space'&&isTyping&&!e.ctrlKey&&!e.altKey&&!e.metaKey&&!e.isComposing){if(solved){e.preventDefault();if(!e.repeat)nextWord();}else if(!current()?.word.includes(' ')){e.preventDefault();}return;}if(e.key==='Tab'&&(isTyping||e.target===document.body||e.target.closest?.('#study-explanation,#word-details')||(mode==='dictation'&&e.target.closest?.('#stage')))&&!e.shiftKey&&!e.ctrlKey&&!e.altKey&&!e.metaKey){e.preventDefault();if(!e.repeat){if(mode==='dictation'&&!solved)revealHint();else toggleWordDetails();}}else if(e.key==='Escape'){e.preventDefault();pause();}else if(e.key==='Enter'&&(solved||isTyping)){e.preventDefault();if(solved)nextWord();else if(answer===current()?.word)complete();else{}}});
