function applyWordFont(){requestAnimationFrame(()=>{$('#passage-rail').style.fontFamily=getComputedStyle($('#word')).fontFamily;if(mode==='cloze'&&passageState&&!passageState.finished)renderPassageLine(false);});document.body.dataset.wordFont=['manrope','serif','system','outfit','dmsans','lora'].includes(db.settings.font)?db.settings.font:'manrope';$('#font-setting').value=document.body.dataset.wordFont;document.fonts.ready.then(()=>requestAnimationFrame(fitPracticeWord));}
