function groupSize(){return [5,10,20,30,50].includes(Number(db.settings.size))?Number(db.settings.size):20;}
function orderedPool(){const pool=eligible(),order=db.settings.order||'smart';if(order==='smart'){const now=Date.now(),due=pool.filter(w=>db.memory?.[w.word]&&db.memory[w.word].due<=now).sort((a,b)=>db.memory[a.word].due-db.memory[b.word].due),fresh=pool.filter(w=>!db.memory?.[w.word]),later=pool.filter(w=>db.memory?.[w.word]?.due>now);const result=[];while(due.length||fresh.length){if(due.length)result.push(due.shift());result.push(...fresh.splice(0,2));}return result.concat(later);}if(order==='weak')return pool.sort((a,b)=>(Number(!!db.mistakes[b.word])-Number(!!db.mistakes[a.word]))||((db.mistakes[b.word]?.count||0)-(db.mistakes[a.word]?.count||0))||((db.mastered[a.word]||0)-(db.mastered[b.word]||0)));if(order==='shuffle'){let seed=Number(db.settings.seed)||9137;for(let i=pool.length-1;i>0;i--){seed=(seed*1664525+1013904223)>>>0;const j=seed%(i+1);[pool[i],pool[j]]=[pool[j],pool[i]];}}return pool;}
for(const [id,key] of [['size','size'],['order','order'],['exit','exit']])$('#'+id+'-setting').onchange=e=>{db.settings[key]=id==='size'?Number(e.target.value):e.target.value;if(id==='order'&&e.target.value==='shuffle')db.settings.seed=Math.floor(Math.random()*4294967295);persist();if(id==='size'||id==='order'){lesson=0;startSession(reviewing);toast('已按新设置开始一组');}};
function effectsAllowed(){return !matchMedia('(prefers-reduced-motion: reduce)').matches;}
function exitGlyph(el,deleting=false){if(deleting)pulseInk(el,true);const effect=db.settings.exit||'fade';if(!effectsAllowed()||effect==='none'||!el?.textContent)return;const r=el.getBoundingClientRect(),ghost=document.createElement('span'),style=getComputedStyle(el);ghost.className='exit-glyph';ghost.setAttribute('aria-hidden','true');ghost.textContent=el.textContent;Object.assign(ghost.style,{left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',fontFamily:style.fontFamily,fontSize:style.fontSize,fontWeight:style.fontWeight,fontStyle:style.fontStyle,lineHeight:style.lineHeight,color:style.color,letterSpacing:style.letterSpacing});const wrap=el.closest('#word-wrap,#preview-scene');if(wrap){let layer=wrap.querySelector('.word-exit-layer');if(!layer){layer=document.createElement('div');layer.className='word-exit-layer';layer.setAttribute('aria-hidden','true');wrap.append(layer);}const bounds=wrap.getBoundingClientRect();ghost.style.position='absolute';ghost.style.left=(r.left-bounds.left)+'px';ghost.style.top=(r.top-bounds.top)+'px';layer.append(ghost);}else (el.closest('dialog')||document.body).append(ghost);const frames=effect==='blur'?[{opacity:.8,transform:'scale(1)'},{opacity:0,transform:'scale(1.08)'}]:effect==='shrink'?[{opacity:.8,transform:'scale(1)'},{opacity:0,transform:'scale(.2)'}]:effect==='slide'?[{opacity:.8,transform:'translateX(0)'},{opacity:0,transform:'translateX(35px)'}]:effect==='float'?[{opacity:.7,transform:'translateY(0)'},{opacity:0,transform:'translateY(-28px) rotate(-6deg) scale(.85)'}]:effect==='fall'?[{opacity:.7,transform:'translateY(0)'},{opacity:0,transform:'translateY(32px) rotate(8deg) scale(.9)'}]:[{opacity:.6},{opacity:0}];ghost.animate(frames,{duration:deleting?220:360,easing:deleting?'cubic-bezier(.22,.6,.35,1)':'cubic-bezier(.4,0,1,1)'}).finished.catch(()=>{}).finally(()=>ghost.remove());}
let sceneAnimation;


var sessionRetries=sessionRetries||{};
function scheduleMemory(correct){if(db.settings.adaptive===false)return;db.memory||={};const w=current(),old=db.memory[w.word]||{streak:0,lapses:0};const streak=correct?Math.min(5,old.streak+1):0;db.memory[w.word]={streak,lapses:old.lapses+(correct?0:1),due:Date.now()+(correct?[1,3,7,14,30][streak-1]*86400000:0)};if(!correct&&(sessionRetries[w.word]||0)<2){sessionRetries[w.word]=(sessionRetries[w.word]||0)+1;queue.splice(Math.min(queue.length,index+4),0,w);$('#session-total').textContent=queue.length;}persist();}
$('#adaptive-setting').onchange=e=>{db.settings.adaptive=e.target.checked;persist();};

function uniqueText(items){const seen=new Set();return items.filter(t=>{if(typeof t!=='string'||!t.trim())return false;const key=t.toLowerCase().replace(/[\s.,;:!?，。；：！？/“”"'’‘-]+/g,'');if(seen.has(key))return false;seen.add(key);return true;}).map(t=>t.trim());}
function uniqueDefinitions(w){const definitions=uniqueText(w.definitions||[]);return definitions.length?definitions:uniqueText([w.en]);}
function richMeanings(w){const entries=uniqueText((w.meanings||[]).map(m=>(m.pos?m.pos+'. ':'')+m.text));return entries.length?entries.slice(0,5).join('\n'):(w.zh||'');}
for(const id of ['exit'])$('#'+id+'-setting').addEventListener('change',previewMotion);
