function beginWordExit(){if(wordExited||!effectsAllowed()||(db.settings.exit||'fade')==='none')return;wordExited=true;[...$('#word').children].forEach(el=>exitGlyph(el));$('#word').style.visibility='hidden';}

function renderExplanations(w){const content=$('#explanation-content'),reading=$('#study-explanation');reading.querySelectorAll('.explanation-outgoing').forEach(el=>el.remove());const outgoingOpacity=Number(getComputedStyle(content).opacity);content.getAnimations().forEach(a=>a.cancel());if(content.textContent.trim()&&effectsAllowed()&&db.settings.motion!=='none'){const old=content.cloneNode(true);old.removeAttribute('id');old.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));old.className='explanation-outgoing';old.setAttribute('aria-hidden','true');Object.assign(old.style,{left:content.offsetLeft+'px',top:content.offsetTop+'px',width:content.getBoundingClientRect().width+'px'});reading.append(old);old.animate([{opacity:outgoingOpacity},{opacity:0}],{duration:180,easing:'ease-out'}).finished.catch(()=>{}).finally(()=>old.remove());}const meaning=$('#meaning');meaning.replaceChildren();const senses=(w.meanings||[]).filter(m=>m.text).slice(0,2);if(!senses.length){const text=document.createElement('span');text.className='meaning-sense';text.textContent=w.zh||'';meaning.append(text);}else{for(const m of senses){const row=document.createElement('span');row.className='meaning-sense';if(m.pos){const pos=document.createElement('span');pos.className='sense-pos';pos.textContent=m.pos+'.';row.append(pos);}const text=document.createElement('span');text.textContent=uniqueText(m.text.split(/[；;]/).map(t=>t.trim()).filter(Boolean)).slice(0,3).join('；');row.append(text);meaning.append(row);}}
 const english=uniqueDefinitions(w).slice(0,1),definition=$('#definition');definition.replaceChildren(...english.map(text=>{const span=document.createElement('span');span.className='english-sense';span.textContent=mode==='follow'?text:redact(text,w.word);return span;}));definition.classList.toggle('reading',english.length>1||english.join('').length>115);definition.closest('.definition-block').hidden=!english.length;
 content.getAnimations().forEach(a=>a.cancel());if(effectsAllowed()&&db.settings.motion!=='none')content.animate([{opacity:0},{opacity:1}],{duration:260,easing:'cubic-bezier(.16,1,.3,1)'});
}

var wordMetrics=wordMetrics||{ms:0,last:0,keys:0,errors:0,back:0,conf:[]};
function trackWordInput(old,next,target){const now=Date.now();if(wordMetrics.last)wordMetrics.ms+=Math.min(10000,now-wordMetrics.last);wordMetrics.last=now;if(next.length<old.length)wordMetrics.back+=old.length-next.length;for(let i=0;i<next.length;i++){if(next[i]===old[i])continue;wordMetrics.keys++;if(next[i]!==target[i]){wordMetrics.errors++;const c=(i+1)+': '+(target[i]||'∅')+' → '+next[i];if(!wordMetrics.conf.includes(c))wordMetrics.conf.push(c);}}}
function recordWord(){db.logs.push({id:crypto.randomUUID(),w:current().word,c:db.course||'cet6',m:mode,t:Date.now(),ms:wordMetrics.ms,k:wordMetrics.keys,e:wordMetrics.errors,b:wordMetrics.back,conf:wordMetrics.conf.slice(0,10),f:!hadError});if(db.logs.length>10000)db.logs.splice(0,db.logs.length-10000);}
