function closeChoice(){if(typeof choiceMenu.hidePopover!=='function')return;if(choiceMenu.matches(':popover-open'))choiceMenu.hidePopover();choiceSelect=null;syncChoiceButtons();}
function openChoice(select){if(choiceSelect===select&&choiceMenu.matches(':popover-open')){closeChoice();return;}closeChoice();choiceSelect=select;const menuParent=select.closest('#settings-dialog')||document.body;if(choiceMenu.parentElement!==menuParent)menuParent.append(choiceMenu);choiceMenu.replaceChildren();choiceMenu.setAttribute('aria-label',choiceButtons.get(select).getAttribute('aria-label'));let active;
 for(const option of select.options){const item=document.createElement('button');item.type='button';item.className='choice-option';item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));item.textContent=option.textContent;if(select.id==='palette-setting')item.append(paletteSwatch(option.value));item.disabled=option.disabled;item.tabIndex=-1;if(option.selected)active=item;item.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));closeChoice();choiceButtons.get(select).focus({preventScroll:true});};choiceMenu.append(item);}
 choiceMenu.showPopover();positionChoiceMenu();syncChoiceButtons();if(effectsAllowed())choiceMenu.animate([{opacity:0,transform:'translateY(-3px) scale(.99)'},{opacity:1,transform:'none'}],{duration:160,easing:'cubic-bezier(.16,1,.3,1)'});(active||choiceMenu.firstElementChild)?.focus({preventScroll:true});if(active)choiceMenu.scrollTop=Math.max(0,active.offsetTop-choiceMenu.clientHeight/2+active.offsetHeight/2);scheduleChoicePosition();
}
function enhanceChoice(select){if(typeof choiceMenu.showPopover!=='function'||choiceButtons.has(select))return;const trigger=document.createElement('button');trigger.type='button';trigger.className='choice-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls','choice-menu');const label=select.getAttribute('aria-label')||[...select.closest('label').childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim();trigger.setAttribute('aria-label',label);trigger.append(document.createTextNode(select.selectedOptions[0]?.textContent||''));trigger.insertAdjacentHTML('beforeend','<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg>');select.classList.add('enhanced-choice');select.tabIndex=-1;select.setAttribute('aria-hidden','true');select.after(trigger);choiceButtons.set(select,trigger);trigger.onclick=()=>openChoice(select);trigger.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openChoice(select);}};select.addEventListener('change',syncChoiceButtons);}
for(const select of $$('#settings-dialog select'))enhanceChoice(select);
syncChoiceButtons();
choiceMenu.addEventListener('toggle',e=>{if(e.newState==='closed'){choiceSelect=null;syncChoiceButtons();}});
choiceMenu.addEventListener('keydown',e=>{const options=[...choiceMenu.querySelectorAll('button:not(:disabled)')],index=options.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();options[e.key==='Home'?0:e.key==='End'?options.length-1:(index+(e.key==='ArrowDown'?1:options.length-1))%options.length]?.focus();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();const trigger=choiceButtons.get(choiceSelect);closeChoice();trigger?.focus({preventScroll:true});}});
$('#settings-dialog').addEventListener('close',closeChoice);

var routeTransitionActive=false,routeTransitionId=0;
function navigateSoft(navigate){stopWheelMotion();const transitionId=++routeTransitionId,page=$(view==='practice'?'#practice-view':'#other-view');page.getAnimations().forEach(a=>a.cancel());const apply=()=>{if(transitionId!==routeTransitionId)return;routeTransitionActive=true;try{navigate();}finally{routeTransitionActive=false;}const destination=$(view==='practice'?'#practice-view':'#other-view');destination.getAnimations().forEach(a=>a.cancel());if(effectsAllowed())destination.animate([{opacity:0},{opacity:1}],{duration:340,easing:'cubic-bezier(.22,1,.36,1)'});};if(effectsAllowed())page.animate([{opacity:1},{opacity:0}],{duration:140,easing:'ease-out'}).finished.then(apply,()=>{});else apply();}
var choicePositionFrame=0;
function positionChoiceMenu(){if(!choiceSelect||!choiceMenu.matches(':popover-open'))return;const trigger=choiceButtons.get(choiceSelect);if(!trigger.getClientRects().length){closeChoice();return;}const rect=trigger.getBoundingClientRect(),panel=trigger.closest('[role=tabpanel]'),clip=panel?.getBoundingClientRect();if(clip&&(rect.bottom<=clip.top+2||rect.top>=clip.bottom-2)){closeChoice();return;}const width=Math.min(Math.max(rect.width,220),innerWidth-32),roomBelow=innerHeight-rect.bottom-12,roomAbove=rect.top-12;choiceMenu.style.width=width+'px';choiceMenu.style.maxHeight=Math.min(300,Math.max(roomAbove,roomBelow))+'px';const desiredLeft=trigger.closest('.record-tools')?rect.left:rect.right-width;choiceMenu.style.left=(Math.max(16,Math.min(desiredLeft,innerWidth-width-16))-document.documentElement.getBoundingClientRect().left)+'px';const height=choiceMenu.offsetHeight,below=roomBelow>=height;choiceMenu.style.top=(below?rect.bottom+6:Math.max(12,rect.top-height-6))+'px';choiceMenu.style.transformOrigin=below?'top right':'bottom right';}
function scheduleChoicePosition(){cancelAnimationFrame(choicePositionFrame);choicePositionFrame=requestAnimationFrame(()=>{positionChoiceMenu();if(choiceSelect&&$('#settings-dialog').getAnimations().some(a=>a.playState==='running'))scheduleChoicePosition();});}
document.addEventListener('scroll',e=>{if(choiceSelect&&e.target!==choiceMenu&&!choiceMenu.contains(e.target))closeChoice();},{capture:true,passive:true});
window.addEventListener('resize',scheduleChoicePosition,{passive:true});window.visualViewport?.addEventListener('resize',scheduleChoicePosition,{passive:true});window.visualViewport?.addEventListener('scroll',scheduleChoicePosition,{passive:true});
for(const rail of $$('.modes'))rail.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...rail.querySelectorAll('button')],i=tabs.indexOf(e.target);if(i<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;tabs[next].click();tabs[next].focus({preventScroll:true});});

function primePracticeAudio(word){const currentAudio=primePronunciation(word);const prefetch=()=>{for(const next of queue.slice(index+1,index+3))primePronunciation(next.word);};if(currentAudio?.readyState>=2)prefetch();else currentAudio?.addEventListener('canplay',prefetch,{once:true});}
$('#key-volume').addEventListener('input',e=>{db.settings.keyVolume=Number(e.target.value)/100;$('#key-volume-value').textContent=e.target.value+'%';if(audio&&keyMaster)keyMaster.gain.setTargetAtTime(db.settings.keyVolume*.8,audio.currentTime,.01);persist();});$('#key-volume').addEventListener('change',()=>keySound());
document.addEventListener('wheel',e=>{if(choiceSelect&&!(e.target instanceof Element&&e.target.closest('#choice-menu')))closeChoice();},{capture:true,passive:true});

setupPassage();

$('#key-tone').onchange=e=>{db.settings.keyTone=e.target.value;persist();keySound(false);};
$('#key-sound-preview').onclick=()=>keySound(false);

// Word sizing is local to the practice surface; ordinary scrolling stays native.
function wordZoom(){const value=Number(db.settings.wordZoom);return Number.isFinite(value)&&value>0?Math.max(.6,Math.min(1.6,value)):1;}
let wordZoomFrame=0,wordZoomSaveTimer=0;
function setWordZoom(value){db.settings.wordZoom=Math.max(.6,Math.min(1.6,value));clearTimeout(wordZoomSaveTimer);wordZoomSaveTimer=setTimeout(persist,180);syncWordZoom();cancelAnimationFrame(wordZoomFrame);wordZoomFrame=requestAnimationFrame(()=>{if(mode==='cloze'&&passageState&&!passageState.finished)renderPassageLine(false);else fitPracticeWord();});}
function syncWordZoom(){document.body.style.setProperty('--word-zoom',wordZoom());$('#word-size').value=String(Math.round(wordZoom()*100));$('#word-size-value').textContent=Math.round(wordZoom()*100)+'%';$('#word-size-reset').disabled=Math.abs(wordZoom()-1)<.005;}
function handleWordZoomWheel(e){if(!e.ctrlKey||e.metaKey||e.altKey||view!=='practice'||$('#settings-dialog').open||!(e.target instanceof Element)||!e.target.closest('#practice-view')||!Number.isFinite(e.deltaY)||e.deltaY===0)return;e.preventDefault();stopWheelMotion();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?120:1);setWordZoom(wordZoom()*Math.exp(-Math.max(-240,Math.min(240,delta))*.0015));}
document.addEventListener('wheel',handleWordZoomWheel,{passive:false});
$('#word-size').addEventListener('input',e=>setWordZoom(Number(e.target.value)/100));
$('#word-size-reset').onclick=()=>setWordZoom(1);
syncWordZoom();

window.addEventListener('pagehide',()=>{clearTimeout(wordZoomSaveTimer);persist();});
